INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"“Did you tell Mei the bridge is closed?” asked Raj.\n“No, I never said that,” replied Tally.","prompt":"“Did you tell Mei the bridge is closed?” asked Raj. “No, I never said that,” replied Tally.","alts":[],"lines":true,"instruction":"Give each speaker their own line.","tip":"A new speaker means a new line. It’s how readers keep track of who’s talking."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('“Did you tell Mei the bridge is closed?” asked Raj.' || char(10) || '“No, I never said that,” replied Tally.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"Mei looked at the clock. “We’re going to be late,” groaned Mei.","prompt":"mei looked at the clock we’re going to be late groaned mei","alts":[],"beat":true,"tip":"Looking isn’t a saying verb, so that sentence ends with a full stop. The speech starts fresh, and the saying verb comes after the comma inside the speech marks."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('Mei looked at the clock. “We’re going to be late,” groaned Mei.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"“Open the gate!” said the guard. Which verb is the best upgrade for “said”?","options":[{"id":"a","text":"whispered","why":"A whisper is quiet. An order has to be heard."},{"id":"b","text":"bellowed"},{"id":"c","text":"giggled","why":"Giggling shows amusement. An order is not a joke."},{"id":"d","text":"wondered","why":"Wondering is a quiet thought or question, not a command."}],"correct":["b"],"pick":1,"explanation":"It’s an order, and orders are shouted. Bellowed shows the volume and the guard’s attitude.","code":"MC_VERB"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('“Open the gate!” said the guard. Which verb is the best upgrade for “said”?') AND COALESCE(json_extract(data, '$.context'), '') = (''));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"“I am going to the Warren,” said Brisk.","instruction":"Rewrite as reported speech.","accepted":["Brisk said (that) she was going to the Warren."],"tip":"In reported speech the tense steps back (am going becomes was going) and I becomes she."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('“I am going to the Warren,” said Brisk.') AND json_extract(data, '$.instruction') = ('Rewrite as reported speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"Daisy told Erica that she would ring the bell the next day.","instruction":"Rewrite as direct speech.","accepted":["Daisy said to Erica, “I will ring the bell tomorrow.”","Daisy told Erica, “I will ring the bell tomorrow.”","Daisy said to Erica, “I’ll ring the bell tomorrow.”","Daisy told Erica, “I’ll ring the bell tomorrow.”"],"tip":"Go back to the speaker’s own words: she would becomes I will, and the next day becomes tomorrow."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('Daisy told Erica that she would ring the bell the next day.') AND json_extract(data, '$.instruction') = ('Rewrite as direct speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 6, NULL, 1, 1, '{"sentence":"The knight walked into the hall and sees a crown.","wrong":["sees"],"fixes":["saw"],"tip":"Keep the verbs in the same time. The story is in the past, so sees should be saw."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 6 AND json_extract(data, '$.sentence') = ('The knight walked into the hall and sees a crown.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"How does Ilse really feel?","options":[{"id":"a","text":"calm","why":"She says she is fine, but what she does tells a different story."},{"id":"b","text":"worried but hiding it"},{"id":"c","text":"bored","why":"Nobody who was bored would stare at one door for an hour."},{"id":"d","text":"angry with Wren","why":"Wren is gentle, and Ilse is not snapping at her. Something else is on her mind."}],"correct":["b"],"pick":1,"explanation":"Her words say “fine”, but her folded arms, the hour spent staring at the door and her refusal to turn around all show she is worried and trying to hide it.","code":"MC_INFER","context":"“I’m fine,” said Ilse, folding her arms.\nWren smiled gently. “You’ve been staring at that door for an hour.”\n“It’s just a door,” Ilse muttered, but she did not turn around.","group":"rbtl-ilse"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('How does Ilse really feel?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I’m fine,” said Ilse, folding her arms.' || char(10) || 'Wren smiled gently. “You’ve been staring at that door for an hour.”' || char(10) || '“It’s just a door,” Ilse muttered, but she did not turn around.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show she isn’t “fine”?","options":[{"id":"a","text":"She is folding her arms."},{"id":"b","text":"She has been staring at the door for an hour."},{"id":"c","text":"She muttered her reply."},{"id":"d","text":"She did not turn around."},{"id":"e","text":"Wren smiled.","why":"Wren’s smile shows how Wren feels, not Ilse."},{"id":"f","text":"The door is mentioned.","why":"The door only matters because of how long Ilse has been staring at it."}],"correct":["a","b","c","d"],"pick":2,"explanation":"Four details give her away: the folded arms, the hour of staring, the muttered reply and the refusal to turn around. Wren smiling and the door being mentioned say nothing about how Ilse feels.","code":"MC_INFER","context":"“I’m fine,” said Ilse, folding her arms.\nWren smiled gently. “You’ve been staring at that door for an hour.”\n“It’s just a door,” Ilse muttered, but she did not turn around.","group":"rbtl-ilse"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Which TWO details show she isn’t “fine”?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I’m fine,” said Ilse, folding her arms.' || char(10) || 'Wren smiled gently. “You’ve been staring at that door for an hour.”' || char(10) || '“It’s just a door,” Ilse muttered, but she did not turn around.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Why does Wren smile gently?","options":[{"id":"a","text":"To show she understands and isn’t scolding"},{"id":"b","text":"To laugh at Ilse for staring at the door","why":"Gently tells us the smile is kind, not mocking."},{"id":"c","text":"To hide that she is annoyed with Ilse","why":"Nothing in the passage shows Wren is annoyed."},{"id":"d","text":"To agree that Ilse is fine","why":"Wren has just pointed out that Ilse is not acting fine."}],"correct":["a"],"pick":1,"explanation":"The word gently and what Wren says next show she has noticed how Ilse is feeling and wants to help, not tell her off.","code":"MC_INFER","context":"“I’m fine,” said Ilse, folding her arms.\nWren smiled gently. “You’ve been staring at that door for an hour.”\n“It’s just a door,” Ilse muttered, but she did not turn around.","group":"rbtl-ilse"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Why does Wren smile gently?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I’m fine,” said Ilse, folding her arms.' || char(10) || 'Wren smiled gently. “You’ve been staring at that door for an hour.”' || char(10) || '“It’s just a door,” Ilse muttered, but she did not turn around.'));
